/**
 * Wharf DeepSWE results — the single source for every DeepSWE figure on the site.
 *
 * The numbers live in wharf-deepswe.json, generated by `npm run wharf:sync -- <wharf checkout>`
 * from Wharf's per-attempt exports (deep-swe/data/*.jsonl). Don't edit the JSON by hand; edit
 * display names in wharf-labels.ts. After a sync, re-read every page that quotes a number in prose.
 * Wharf's docs/RESULTS.md quotes some earlier runs of the same configurations; don't mix them in.
 */
import data from "./wharf-deepswe.json";
import { deepSweHarnessNames, deepSweModelNames, deepSweRunLabels } from "./wharf-labels";

export const wharfSource = "https://github.com/bartr/wharf";
export const wharfCommit = data.commit;
export const wharfDate = "Oct–Nov 2026";
export const taskCount = data.taskCount;

export type WharfRun = {
  id: string;
  model: string;
  harness: string;
  /** Harness release the run used. */
  version: string;
  effort: string;
  /** Guidance pack copied into the agent's config, e.g. "hve-core"; null for a plain run. */
  guidance: string | null;
  attemptsPerTask: number;
  /** Planned attempts; missing attempts count as failures, never shrink this. */
  planned: number;
  /** Attempts that actually ran. */
  retained: number;
  passing: number;
  /** Attempts with at least one pre-existing (P2P) test failing after the change. */
  regressions: number;
  /** Attempts cut short by a timeout, crash, cancellation or infrastructure error. */
  errors: number;
  /** Errored attempts whose patch still passed the verifier. */
  erroredPasses: number;
  /** Mean cost per attempt with cost data; null when no cost was recorded. */
  costPerAttempt: number | null;
  /** Share of planned attempts with cost data, 0–1. */
  costCoverage: number;
  /** Task-weighted mean agent time per attempt, seconds. */
  agentSeconds: number;
  /** Task-clustered standard error of the pass rate, 0–1. */
  se: number;
  /** Tasks solved on every planned attempt. */
  tasksAllPass: number;
  /** Tasks never solved on any attempt. */
  tasksNoPass: number;
  /** Mean input tokens per attempt; null where the harness didn't record them. */
  inputTokens: number | null;
};

const allRuns: WharfRun[] = data.arms.map((a) => ({
  ...a,
  model: deepSweRunLabels[a.id] ?? deepSweModelNames[a.model],
  harness: deepSweHarnessNames[a.harness],
}));

/** The main comparison: every run without an added guidance pack. */
export const runs = allRuns.filter((r) => !r.guidance);

/** HVE Core runs, each paired with the otherwise identical plain run ("…-max-hve-1.0.77" → "…-max-1.0.77"). */
export const guidancePairs = allRuns
  .filter((r) => r.guidance === "hve-core")
  .map((guided) => ({ guided, base: run(guided.id.replace("-hve-", "-")) }));

export const passRate = (r: WharfRun) => r.passing / r.planned;

/** Half-width of the 95% range on a run's pass rate, in percentage points. */
export const range95 = (r: WharfRun) => 1.96 * r.se * 100;

export function run(id: string) {
  const found = allRuns.find((r) => r.id === id);
  if (!found) throw new Error(`Unknown Wharf run: ${id}`);
  return found;
}

/** Tasks solved on some attempts but not all. */
export const tasksMixed = (r: WharfRun) => taskCount - r.tasksAllPass - r.tasksNoPass;

/**
 * Estimated cost per passing attempt: mean cost per costed attempt × planned attempts ÷ passes.
 * Null without cost data or below 95% cost coverage, where the estimate would lean on too few rows.
 */
export const costPerPass = (r: WharfRun) =>
  r.costPerAttempt === null || r.costCoverage < 0.95 ? null : (r.costPerAttempt * r.planned) / r.passing;

export const totalPlanned = runs.reduce((sum, r) => sum + r.planned, 0);

export const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
export const usd = (x: number | null) => (x === null ? "—" : `$${x.toFixed(2)}`);

/** Caveats that belong to one run, shown as footnotes in the results table. */
export function runNotes(r: WharfRun): string[] {
  const notes: string[] = [];
  if (r.model === "Auto") {
    notes.push("Auto is Copilot's model router. The data doesn't record which model it picked for each attempt.");
  }
  if (r.model.startsWith("HydraFusion")) notes.push("HydraFusion is a Copilot model router, not a single model.");
  if (r.retained < r.planned) {
    notes.push(`${r.planned - r.retained} planned attempts never ran. They count as failures.`);
  }
  if (r.errors / r.planned >= 0.1) {
    notes.push(`${r.errors} of ${r.planned} attempts were cut short by a timeout, crash or cancellation. Each was still graded on the patch it left; ${r.erroredPasses} of them passed.`);
  }
  if (r.costPerAttempt === null) notes.push("No cost was recorded for this run.");
  else if (r.costCoverage < 0.98) {
    const share = (r.costCoverage * 100).toFixed(1).replace(/\.0$/, "");
    notes.push(`Cost was recorded for ${share}% of attempts. $/attempt averages those only.`);
  }
  return notes;
}

/**
 * Meta's published DeepSWE 1.1 results (5 attempts per task, each model in its own agent
 * product), read from the chart in Meta's Muse Spark 1.2 announcement. Meta publishes no
 * per-task data, so these comparisons are unpaired.
 */
export const metaSource = "https://research.meta.ai/blog/introducing-muse-code-and-muse-spark-1-2";
export const metaComparisons = [
  { runId: "muse-spark-1.2-contributor-xhigh-0.1.0", metaHarness: "Muse Code", meta: 0.593 },
  { runId: "cc-claude-opus-5-max-2.1.220", metaHarness: "Claude Code", meta: 0.65 },
  { runId: "copilot-gpt-5.6-terra-max-1.0.77", metaHarness: "Codex", meta: 0.648 },
].map((c) => ({ ...c, run: run(c.runId) }));
